{
    "investigate": [
        {
            "tool": "sql",
            "query": "SELECT service, used_mb, quota_mb FROM storage WHERE service IN ('worker', 'sync-job') ORDER BY service",
            "why": "Check if worker and sync-job are hitting disk quota limits, which would explain the 'disk quota exceeded' errors"
        },
        {
            "tool": "logs",
            "service": "payment-service",
            "level": "ERROR",
            "contains": "provider request failed",
            "why": "Get more details about payment provider 503 errors to understand if this is an external dependency issue"
        }
    ],
    "hypotheses": [
        {
            "service": "worker",
            "kind": "resource_exhaustion",
            "mechanism": "Worker service has exhausted its disk quota, causing invoice file write failures and message processing errors",
            "supporting": ["E16", "E17", "E3", "E8", "E10"],
            "refuting": ["E23"],
            "explains": ["M3_dead_letters", "M2_error_burst"],
            "repair_plan": [{"action": "restart_service", "params": {"service": "worker"}}]
        },
        {
            "service": "payment-provider",
            "kind": "external_dependency",
            "mechanism": "External payment provider is returning 503 errors, causing payment failures and reduced payment processing rates",
            "supporting": ["E15", "E4", "E13", "E12", "E14"],
            "refuting": ["E21"],
            "explains": ["I7_payments_succeed"],
            "repair_plan": []
        }
    ],
    "summary": "Two independent causes: worker disk quota exhaustion causing processing failures, and external payment provider downtime causing payment failures"
}
